async function uploadParaGeminiFiles(buffer, mimeType, apiKey, displayName) {
  const startResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/upload/v1beta/files?key=' + apiKey,
    headers: {
      'X-Goog-Upload-Protocol': 'resumable',
      'X-Goog-Upload-Command': 'start',
      'X-Goog-Upload-Header-Content-Length': String(buffer.length),
      'X-Goog-Upload-Header-Content-Type': mimeType,
      'Content-Type': 'application/json',
    },
    body: { file: { display_name: displayName } },
    json: true,
    returnFullResponse: true,
  });

  const uploadUrl = startResp.headers['x-goog-upload-url'] || startResp.headers['X-Goog-Upload-URL'];
  if (!uploadUrl) {
    throw new Error('Sem X-Goog-Upload-URL na resposta de start. Headers: ' + JSON.stringify(Object.keys(startResp.headers || {})));
  }

  const finalizeResp = await this.helpers.httpRequest({
    method: 'PUT',
    url: uploadUrl,
    headers: {
      'X-Goog-Upload-Offset': '0',
      'X-Goog-Upload-Command': 'upload, finalize',
    },
    body: buffer,
    json: false,
    encoding: null,
  });

  let parsed = finalizeResp;
  if (Buffer.isBuffer(finalizeResp)) parsed = JSON.parse(finalizeResp.toString('utf8'));
  else if (typeof finalizeResp === 'string') parsed = JSON.parse(finalizeResp);
  const fileUri = parsed && parsed.file && parsed.file.uri;
  if (!fileUri) {
    throw new Error('Sem file.uri na resposta de finalize: ' + JSON.stringify(parsed).slice(0, 300));
  }
  return { fileUri, mimeType: (parsed.file && parsed.file.mimeType) || mimeType };
}

const original = $('Formatar Prompt e Dados').first().json;
const logoItem = $input.first();

let logoFileUri = null;
let logoMimeType = null;
let logoDebugError = null;
let logoBufferSha256 = null;
let logoBufferLength = null;

if (logoItem.binary && logoItem.binary.data) {
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
    logoBufferLength = buffer.length;
    logoBufferSha256 = buffer.slice(0, 16).toString('hex') + '...' + buffer.slice(-16).toString('hex');
    const detectedMime = logoItem.binary.data.mimeType;
    const mimeType = (detectedMime && detectedMime.startsWith('image/')) ? detectedMime : 'image/png';
    const uploaded = await uploadParaGeminiFiles.call(this, buffer, mimeType, original.gemini_api_key, 'logo');
    logoFileUri = uploaded.fileUri;
    logoMimeType = uploaded.mimeType;
  } catch (e) {
    logoDebugError = String(e && e.message || e);
  }
} else {
  logoDebugError = 'sem binary.data no item da Baixar Logo';
}

return [{ json: { ...original, logoFileUri, logoMimeType, logoDebugError, logoBufferSha256, logoBufferLength } }];

const data = $input.first().json;
return data.products.map((product, index) => ({
  json: { ...data, currentProduct: product, productIndex: index }
}));

const original = $('Separar Produtos').item.json;
const results = $json.images_results || [];
const imageUrl = (results[0] && (results[0].original || results[0].thumbnail)) || null;
return { json: { ...original, productImageUrl: imageUrl } };

