const original = $('Separar Produtos').item.json;
const fotoItem = $input.item;

let productImageFileUri = null;
let productImageMimeType = null;
let productImageDebugError = null;

try {
  const customDataUri = original.currentProduct.custom_image_base64;
  if (customDataUri) {
    const m = /^data:([^;]+);base64,(.+)$/.exec(customDataUri);
    const mimeType = m ? m[1] : 'image/png';
    const buffer = Buffer.from(m ? m[2] : customDataUri, 'base64');
    const uploaded = await uploadParaGeminiFiles.call(this, buffer, mimeType, original.gemini_api_key, 'produto');
    productImageFileUri = uploaded.fileUri;
    productImageMimeType = uploaded.mimeType;
  } else if (fotoItem.binary && fotoItem.binary.data) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
    const detectedMime = fotoItem.binary.data.mimeType;
    const mimeType = (detectedMime && detectedMime.startsWith('image/')) ? detectedMime : 'image/jpeg';
    const uploaded = await uploadParaGeminiFiles.call(this, buffer, mimeType, original.gemini_api_key, 'produto');
    productImageFileUri = uploaded.fileUri;
    productImageMimeType = uploaded.mimeType;
  } else {
    productImageDebugError = 'sem foto customizada nem binary.data da busca';
  }
} catch (e) {
  productImageDebugError = String(e && e.message || e);
}

return { json: { ...original, productImageFileUri, productImageMimeType, productImageDebugError } };

const items = $input.all();

const productImages = items.map(item => ({
  ean: item.json.currentProduct.ean,
  fileUri: item.json.productImageFileUri || null,
  mimeType: item.json.productImageMimeType || null,
}));

const base = items[0].json;
return [{
  json: {
    org: base.org,
    products: base.products,
    style: base.style,
    aspectRatio: base.aspectRatio,
    prompt: base.prompt,
    gemini_api_key: base.gemini_api_key,
    serpapi_key: base.serpapi_key,
    logoFileUri: base.logoFileUri,
    logoBufferSha256: base.logoBufferSha256,
    logoBufferLength: base.logoBufferLength,
    logoMimeType: base.logoMimeType,
    productImages,
  }
}];

// Monta as partes da mensagem pro Gemini referenciando os arquivos já
// subidos na API de Files (fileData.fileUri), em vez de embutir base64.
const data = $input.first().json;
const imageParts = [];

if (data.logoFileUri) {
  imageParts.push({ fileData: { fileUri: data.logoFileUri, mimeType: data.logoMimeType || 'image/png' } });
}

for (const img of data.productImages) {
  if (img.fileUri) {
    imageParts.push({ fileData: { fileUri: img.fileUri, mimeType: img.mimeType || 'image/jpeg' } });
  }
}

return [{ json: { ...data, imageParts } }];

// Extrai a imagem gerada pelo Gemini
const response = $input.first().json;

const parts = response?.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find(p => p.inlineData?.mimeType?.startsWith('image/'));

if (!imagePart) {
  throw new Error('Gemini não retornou nenhuma imagem. Verifique o prompt e as permissões da API.');
}

const base64Image = imagePart.inlineData.data;
const mimeType = imagePart.inlineData.mimeType;

return [{
  json: {
    base64Image,
    mimeType,
    fileExtension: mimeType.includes('png') ? 'png' : 'jpg',
  }
}];

const imageData = $('Extrair Imagem Gerada').item.json;
const dataUrl = `data:${imageData.mimeType};base64,${imageData.base64Image}`;
return [{ json: { image_url: dataUrl, success: true } }];

